module MongeMaxArea(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire signed [11:0] matrix_flat [0:8],\n    output reg [5:0] max_area,\n    output reg done\n);\n\n    parameter DATA_WIDTH = 12;\n    parameter AREA_WIDTH = 6;\n\n    // State machine states\n    localparam [0:0] IDLE = 1'b0;\n    localparam [0:0] DONE_ST = 1'b1;\n    reg [0:0] state;\n\n    // Edge detection for start\n    reg start_prev;\n\n    // Registered matrix after start\n    reg signed [11:0] matrix_reg [0:8];\n\n    // Combinational max area tracking\n    reg [5:0] temp_max_area;\n\n    integer row_start, row_end, col_start, col_end;\n    integer i, j, k, l;\n    integer area;\n    reg is_monge;\n    reg signed [DATA_WIDTH-1:0] element_ik, element_jl, element_il, element_jk;\n\n    always @* begin\n        temp_max_area = 6'd0;\n        for (row_start = 0; row_start < 3; row_start = row_start + 1) begin\n            for (row_end = row_start; row_end < 3; row_end = row_end + 1) begin\n                for (col_start = 0; col_start < 3; col_start = col_start + 1) begin\n                    for (col_end = col_start; col_end < 3; col_end = col_end + 1) begin\n                        // Check Monge condition\n                        is_monge = 1'b1;\n                        for (i = row_start; i <= row_end; i = i + 1) begin\n                            for (j = i + 1; j <= row_end; j = j + 1) begin\n                                for (k = col_start; k <= col_end; k = k + 1) begin\n                                    for (l = k + 1; l <= col_end; l = l + 1) begin\n                                        element_ik = matrix_reg[i * 3 + k];\n                                        element_jl = matrix_reg[j * 3 + l];\n                                        element_il = matrix_reg[i * 3 + l];\n                                        element_jk = matrix_reg[j * 3 + k];\n                                        if (($signed(element_ik) + $signed(element_jl)) > \n                                            ($signed(element_il) + $signed(element_jk))) begin\n                                            is_monge = 1'b0;\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                        // Calculate area\n                        area = (row_end - row_start + 1) * (col_end - col_start + 1);\n                        if (is_monge && (area > temp_max_area)) begin\n                            temp_max_area = area;\n                        end\n                    end\n                end\n            end\n        end\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            max_area <= 6'd0;\n            start_prev <= 1'b0;\n            // Initialize matrix_reg\n            for (integer idx = 0; idx < 9; idx = idx + 1) begin\n                matrix_reg[idx] <= 12'sd0;\n            end\n        end else begin\n            start_prev <= start;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (~start_prev && start) begin\n                        // Latch matrix\n                        for (integer idx = 0; idx < 9; idx = idx + 1) begin\n                            matrix_reg[idx] <= matrix_flat[idx];\n                        end\n                        state <= DONE_ST;\n                    end\n                end\n\n                DONE_ST: begin\n                    max_area <= temp_max_area;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule